			/**
			 * 문제상태및원인분류코드 상위분류 선택시 하위 분류가 없는경우 비활성화 처리 
			 * @param {Number} vsNewVal 선택한 분류콤보박스 value
			 * @param {String} codeId 선택한 분류 공통코드 아이디
			    PROBM_STTS_LCLAS_SE_CD 문제상태대분류
			    PROBM_STTS_MLSFC_SE_CD 문제상태중분류
			    PROBM_STTS_SCLAS_SE_CD 문제상태소분류
			    PROBM_CAS_LCLAS_SE_CD  문제원인대분류
			    PROBM_CAS_SCLAS_SE_CD  문제원인소분류
			 */
			function selectProbmSection(vsNewVal, CodeId) {
			    
			    // param Null 일경우 return false
			    if (ValueUtil.isNull(vsNewVal)) return false;
			    if (ValueUtil.isNull(CodeId)) return false;
			    
			    // 문제상태대분류, 문제원인대/소분류 기타(입력 선택시)
			    comboEtcValueCheck(CodeId);
			    
			    // 문제상태및원인 분류 콤보박스
			    var vcCmbProbmLv2 = app.lookup("cmb_PROBM_STTS_MLSFC_SE_CD");
			    var vcCmbProbmLv3 = app.lookup("cmb_PROBM_STTS_SCLAS_SE_CD");
			    
			    // 문제상태대분류
			    if (CodeId == "PROBM_STTS_LCLAS_SE_CD") {
			        // 대분류 선택에 따른 하위 콤보 값 필터링
			        vcCmbProbmLv2.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        vcCmbProbmLv3.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 대분류 변경시 하위 콤보 초기화
			        vcCmbProbmLv2.putValue("");
			        vcCmbProbmLv3.putValue("");
			        // 문제상태중분류
			    } else if (CodeId == "PROBM_STTS_MLSFC_SE_CD") {
			        // 중분류 선택에 따른 하위 콤보 값 필터링
			        vcCmbProbmLv3.setFilter("value == '' || getValue('UP_CMMNS_CD_VALUE') =='" + vsNewVal + "'");
			        // 중분류 변경시 하위 콤보 초기화
			        vcCmbProbmLv3.putValue("");
			    }
			    
			    // 하위분류 콤보박스 rowCount 개수 확인
			    var rowCnt = [vcCmbProbmLv2.getItemCount(), vcCmbProbmLv3.getItemCount()];
			    rowCnt.forEach(function(rowCnt, idx) {
			//        console.log("rowCnt=[" + idx + "] = " + rowCnt + "");
			        
			        // 하위분류가 유무 여부 체크
			        if (rowCnt == 0) {
			            /* 하위분류 없음 */
			            switch (idx) {
			                case 0:
			                    util.Control.setEnable(app, false, "cmb_PROBM_STTS_MLSFC_SE_CD");
			                    break;
			                case 1:
			                    util.Control.setEnable(app, false, "cmb_PROBM_STTS_SCLAS_SE_CD");
			                    break;
			            }
			        } else {
			            switch (idx) {
			                case 0:
			                    util.Control.setEnable(app, true, "cmb_PROBM_STTS_MLSFC_SE_CD");
			                    break;
			                case 1:
			                    util.Control.setEnable(app, true, "cmb_PROBM_STTS_SCLAS_SE_CD");
			                    break;
			            }
			        }
			    });
			}

			function comboEtcValueCheck(CodeId) {
			    
			    if (ValueUtil.isNull(CodeId)) return false;
			    
			    var vcGrdProbmFormLot = app.lookup("grp3").getLayout(); // 프리폼 레이아웃
			    var vcProbmSttsCasCode = app.lookup("dsEmrgIntrvnDetail"); // dataMap
			    
			    var vcCmbLv1Val = vcProbmSttsCasCode.getValue(0, "PROBM_STTS_LCLAS_SE_CD");
			    var vcCmbLv2Val = vcProbmSttsCasCode.getValue(0, "PROBM_STTS_MLSFC_SE_CD");
			    var vcCmbLv3Val = vcProbmSttsCasCode.getValue(0, "PROBM_STTS_SCLAS_SE_CD");
			    
			    var dsProbmSttsLclasSeCd = app.lookup("dsProbmSttsLclasSeCd");
			    var dsProbmSttsMlsfcSeCd = app.lookup("dsProbmSttsMlsfcSeCd");
			    var dsProbmSttsSclasSeCd = app.lookup("dsProbmSttsSclasSeCd");
			//    console.log(CodeId);
			    switch (CodeId) {
			        
			        case "PROBM_STTS_LCLAS_SE_CD": // 문제상태대분류
			            var arrCmbLv1Val = [];
			            var arrCmbLv1EtcVal = [];
			            
			            dsProbmSttsLclasSeCd.getRowDataRanged().forEach(function(dsProbmSttsLclasSeCd, idx) {
			                
			                var valueNm = dsProbmSttsLclasSeCd.CMMNS_CD_VALUE_NM.substr(0, 2);
			                var value = dsProbmSttsLclasSeCd.CMMNS_CD_VALUE;
			                if (valueNm == "기타") {
			                    arrCmbLv1EtcVal.push(value);
			                } else {
			                    arrCmbLv1Val.push(value);
			                }
			            });
			            for (var i = 0; i < arrCmbLv1Val.length; i++) {
			                if (arrCmbLv1EtcVal[i] == vcCmbLv1Val) {
			                    vcGrdProbmFormLot.setColumnVisible(3, true);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, true);
			                    util.Control.setFocus(app, "ipb_ACTN_ETC_CN");
			                } else if (arrCmbLv1Val[i] == vcCmbLv1Val) {
			                    util.Control.reset(app, "ipb_ACTN_ETC_CN");
			                    vcGrdProbmFormLot.setColumnVisible(3, false);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, false);
			                }
			            }
			            break;
			        case "PROBM_STTS_MLSFC_SE_CD": // 문제상태중분류
			            var arrCmbLv2Val = [];
			            var arrCmbLv2EtcVal = [];
			            
			            dsProbmSttsMlsfcSeCd.getRowDataRanged().forEach(function(dsProbmSttsMlsfcSeCd, idx) {
			                var valueNm = dsProbmSttsMlsfcSeCd.CMMNS_CD_VALUE_NM.substr(0, 2);
			                var value = dsProbmSttsMlsfcSeCd.CMMNS_CD_VALUE;
			                
			                // 기타 다건일 경우
			                if (valueNm == "기타") {
			                    arrCmbLv2EtcVal.push(value);
			                } else {
			                    arrCmbLv2Val.push(value);
			                }
			            });
			            for (var i = 0; i < arrCmbLv2Val.length; i++) {
			                if (arrCmbLv2EtcVal[i] == vcCmbLv2Val) {
			                    vcGrdProbmFormLot.setColumnVisible(3, true);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, true);
			                    util.Control.setFocus(app, "ipb_ACTN_ETC_CN");
			                } else if (arrCmbLv2Val[i] == vcCmbLv2Val) {
			                    util.Control.reset(app, "ipb_ACTN_ETC_CN");
			                    vcGrdProbmFormLot.setColumnVisible(3, false);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, false);
			                }
			            }
			            break;
			        case "PROBM_STTS_SCLAS_SE_CD": // 문제상태소분류
			            var arrCmbLv3Val = [];
			            var arrCmbLv3EtcVal = [];
			            
			            dsProbmSttsSclasSeCd.getRowDataRanged().forEach(function(dsProbmSttsSclasSeCd, idx) {
			                
			                var valueNm = dsProbmSttsSclasSeCd.CMMNS_CD_VALUE_NM.substr(0, 2);
			                var value = dsProbmSttsSclasSeCd.CMMNS_CD_VALUE;
			                
			                if (valueNm == "기타") {
			                    arrCmbLv3EtcVal.push(value);
			                } else {
			                    arrCmbLv3Val.push(value);
			                }
			            });
			            
			            for (var i = 0; i < arrCmbLv3Val.length; i++) {
			                if (arrCmbLv3EtcVal[i] == vcCmbLv3Val) {
			                    vcGrdProbmFormLot.setColumnVisible(3, true);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, true);
			                    util.Control.setFocus(app, "ipb_ACTN_ETC_CN");
			                } else if (arrCmbLv3Val[i] == vcCmbLv3Val) {
			                    util.Control.reset(app, "ipb_ACTN_ETC_CN");
			                    vcGrdProbmFormLot.setColumnVisible(3, false);
			                    //                    vcGrdProbmFormLot.setRowVisible(3, false);
			                }
			            }
			            break;
			    }
			}

