			function probmSttsSeCdComboBoxReadOnly (){
			    
			    // 대,중,소 값이 없는경우
			    // 대분류에만 값이 있는 경우
			    // 대분류, 중분류에만 값이 있는 경우
			    // 대분류, 중분류, 소분류에 값이 있는 경우
			    // 대분류, 중분류, 소분류, 기타칸에 값이 있는경우

			    var dsEmrgIntrvnDetail = app.lookup("dsEmrgIntrvnDetail");
			    
			    var vcLv1Combo  = app.lookup("cmb_PROBM_STTS_LCLAS_SE_CD");    
			    var vcLv2Combo  = app.lookup("cmb_PROBM_STTS_MLSFC_SE_CD");    
			    var vcLv3Combo  = app.lookup("cmb_PROBM_STTS_SCLAS_SE_CD");    
			    var vcEtcInput  = app.lookup("ipb_ACTN_ETC_CN");
			    
			    var vcGrdProbmFormLot = app.lookup("grp3").getLayout(); // 프리폼 레이아웃
			    
			    var vcLv1ComboVal = dsEmrgIntrvnDetail.getValue(0, "PROBM_STTS_LCLAS_SE_CD");
			    var vcLv2ComboVal = dsEmrgIntrvnDetail.getValue(0, "PROBM_STTS_MLSFC_SE_CD");
			    var vcLv3ComboVal = dsEmrgIntrvnDetail.getValue(0, "PROBM_STTS_SCLAS_SE_CD");
			    var vcEtcInputVal = dsEmrgIntrvnDetail.getValue(0, "ACTN_ETC_CN");
			    
			    if (vcLv1ComboVal != "" && vcLv2ComboVal == "" && vcLv3ComboVal == ""){
			        vcLv1Combo.style.setClasses("non-readonly");
			        vcLv2Combo.enabled = false;
			        vcLv3Combo.enabled = false;
			        probmSttsSeCdComboBoxEtcReadOnly("PROBM_STTS_LCLAS_SE_CD");
			        
			    }else if(vcLv1ComboVal != null && vcLv2ComboVal != "" && vcLv3ComboVal == ""){
			        vcLv1Combo.style.setClasses("non-readonly");
			        vcLv2Combo.style.setClasses("non-readonly");
			        vcLv3Combo.enabled = false;
			        probmSttsSeCdComboBoxEtcReadOnly("PROBM_STTS_MLSFC_SE_CD");
			    }else if(vcLv1ComboVal != "" && vcLv2ComboVal != "" && vcLv3ComboVal != ""){
			        vcLv1Combo.style.setClasses("non-readonly");
			        vcLv2Combo.style.setClasses("non-readonly");
			        vcLv3Combo.style.setClasses("non-readonly");
			        probmSttsSeCdComboBoxEtcReadOnly("PROBM_STTS_SCLAS_SE_CD");
			        
			    }else if(vcLv1ComboVal != "" && vcLv2ComboVal != "" && vcLv3ComboVal != "" && vcEtcInputVal != ""){
			        vcLv1Combo.style.setClasses("non-readonly");
			        vcLv2Combo.style.setClasses("non-readonly");
			        vcLv3Combo.style.setClasses("non-readonly");
			        vcGrdProbmFormLot.setColumnVisible(3, true);
			    }
			}

