			/*
			 * 루트 컨테이너에서 property-change 이벤트 발생 시 호출.
			 * 앱의 속성이 변경될 때 발생하는 이벤트 입니다.
			 */
			function onBodyPropertyChange( /* cpr.events.CPropertyChangeEvent */ e) {
			    
			    /* 2023-02-21 YOO.CHI.HOON 버튼권한 최종 추가*/
			    if(e.property == "btnUseYn"){
			        inqUseYn = e.newValue["INQ_BUTTON_USE_YN"];         //조회버튼사용여부 - 프론트에서는 사용하지 않을것으로 보입니다
			        dtlUseYn = e.newValue["DTL_INQ_BUTTON_USE_YN"];     //상세조회버튼사용여부
			        mngUseYn = e.newValue["MNG_BUTTON_USE_YN"];       //관리버튼사용여부 - 프론트에서는 사용하지 않을것으로 보입니다      
			        regUseYn = e.newValue["REG_BUTTON_USE_YN"];         //등록버튼사용여부
			        mdfUseYn = e.newValue["MDFCN_BUTTON_USE_YN"];       //수정버튼사용여부
			        delUseYn = e.newValue["DEL_BUTTON_USE_YN"];         //삭제버튼사용여부
			        
			        fn_setDtlCrud(msCrudType);         
			        
			    }     
			    if (e.property == "type") {

			        if (e.newValue == "READ") {
			            
			            msCrudType = 'READ';
			            
			        } else if (e.newValue == "CREATE") {
			            
			            // insert rowData 생성
			            app.lookup("dsEmrgIntrvnDetail").insertRow(0);
			            
			            msCrudType = 'CREATE';
			            
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "UNT_TASKWK_SE_CD", untTaskwk);
			            
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "PRCS_YMD"      , vsToday);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "ACTN_YMD"      , vsToday);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "CONSTT_NO"     , enfsnNo);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "CONSTT_NM"     , userNm);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "CONSTT_INST_NO", instNo);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "CONSTT_INST_NM", instNm);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "RCPT_YMD"           , vsToday);
			            app.lookup("dsEmrgIntrvnDetail").setValue(0, "RCPT_HR"            , vsTime);
			            
			            app.lookup("sipb_TRPR_NM").focus();
			   
			            fn_setDtlCrud(msCrudType);     
			        }
			    } else if (e.property == "data") {
			        
			        app.lookup("dmSearch").build(e.newValue);
			        
			        msCrudType = 'READ';        
			        
			        // 발굴목록(부모) 화면에서 파라메터 넘겨준 갓 셋팅(DSCSN_NO => EMRG_INTRVN_NO)
			        var vcDscsnNo = app.lookup("dmSearch").getValue("DSCSN_NO");
			        app.lookup("dmSearch").setValue("EMRG_INTRVN_NO", vcDscsnNo);
			        
			        // 상세조회
			        doDetail();
			        fn_setDtlCrud(msCrudType);     
			    }
			}

