			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    var btnSave = e.control;
			    
			    var dsEmrgIntrvnDetail = app.lookup("dsEmrgIntrvnDetail");
			    var updateState        = dsEmrgIntrvnDetail.getRowStatedCount(cpr.data.tabledata.RowState.UPDATED);
			    
			    if (msCrudType == "UPDATE"){
			        
			//        if (updateState <= 0) {
			//            var psTitle = "정보수정";
			//            var psMsgId = "수정된 사항이 없습니다.";
			//            
			//            util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			//            return false;
			//        }
			    }
			    
			 // 미지원/삭제 코드 선택 확인
			     var bFlag = true;
			     var sMsg  = "";
			 
			     var comList = AppUtil.getComponentList(app, "grpData", "combobox");
			     for(var i=0; i<comList.length; i++) {
			         var comObj = comList[i];
			 
			         var sText       = comObj.text;
			         var sFiledLabel = comObj.fieldLabel;
			 
			         if(comObj.enabled && !comObj.readonly) {
			             if(sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			                 bFlag = false;
			 
			                 if(ValueUtil.isNull(sMsg)) {
			                     sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                 } else {
			                     sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                 }
			             }
			         }
			     }
			     
			     comList = AppUtil.getComponentList(app, "grpData", "radiobutton");
			     for(var i=0; i<comList.length; i++) {
			         var comObj = comList[i];
			 
			         var sText       = comObj.text;
			         var sFiledLabel = comObj.fieldLabel;
			 
			         if(comObj.enabled && !comObj.readonly) {
			             if(sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			                 bFlag = false;
			 
			                 if(ValueUtil.isNull(sMsg)) {
			                     sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                 } else {
			                     sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                 }
			             }
			         }
			     }
			 
			     if(!bFlag) {
			         util.Msg.alert(app, sMsg);
			         return false;
			     }    
			    
			    var sTrprNm            = app.lookup("dsEmrgIntrvnDetail").getRowData(0).TRPR_NM;
			    if (sTrprNm == null || sTrprNm == "" || sTrprNm.length < 0) {
			        var psTitle = "대상자정보";
			        var psMsgId = "대상자가 선택되지 않았습니다.\n대상자를 조회하여 선택하시기 바랍니다.";
			        
			        util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			        return false;
			    }
			    
			    if (!util.validate(app, "sipb_CONSTT_NM")) return false;  // 상담자명
			    if (!util.validate(app, "grpContsDef2")) return false;  // 의뢰경로 required 체크포함
			    if (!util.validate(app, "grpContsDef3")) return false;  // 조치내용 required 체크포함
			    
			    var actnEtcCn = app.lookup("txa_ACTN_ETC_CN").value;
			    var actnEtcCnLen = (new TextEncoder().encode(actnEtcCn)).length;
			    if (actnEtcCnLen > 2000) {
			        var msg = "조치 내용의 길이가 " + actnEtcCnLen + " byte 로서 입력 최대 길이인 2000 byte 를 초과합니다.";
			        msg += "\n영문자, 숫자는 1 byte, 한글은 한 글자가 3 byte 입니다.";
			        msg += "\n조치 내용의 길이를 조정해주시기 바랍니다.";
			        
			        util.Msg.alert(app, msg);
			        return false;
			    }
			    
			    util.Msg.confirm(app, "입력하신 내용을 저장하시겠습니까?", null, function() {
			        
			        // 저장 하시겠습니까?
			//        doSave(); // 상세저장
			        
			        var vcFileUpload = app.lookup("cmnsinglefileupload_ATFINO");
			        vcFileUpload.send(doSave);         
			        
			    }, function() {
			        
			    }, "긴급구조 등록");
			}
